// ===== Read Lead Webhook =====
// Accepts two shapes: Meta's leadgen webhook (which carries only an id) and a plain
// JSON post from a web form. Emits one item per lead so the loop can take them singly.
const out = [];
const S = (v) => (v == null ? '' : String(v));

for (const it of $input.all()) {
  const j = it.json || {};
  const body = (j.body && typeof j.body === 'object') ? j.body : j;

  // ---- Meta lead ads ----
  if (S(body.object) === 'page' && Array.isArray(body.entry)) {
    for (const entry of body.entry) {
      for (const change of (entry.changes || [])) {
        if (S(change.field) !== 'leadgen') continue;
        const v = change.value || {};
        const leadgenId = S(v.leadgen_id);
        if (!leadgenId) continue;
        out.push({ json: {
          source: 'facebook',
          source_key: S(v.form_id),
          page_id: S(v.page_id),
          leadgen_id: leadgenId,
          ad_id: S(v.ad_id), adgroup_id: S(v.adgroup_id),
          created_time: v.created_time || null,
          needsFetch: true,
          dedupe_key: 'fb:' + leadgenId,
          formData: {},
          sql: 'SELECT campaign_for($1) AS campaign, claim_once($2) AS fresh, $3::jsonb AS lead',
        } });
      }
    }
    // Meta sends one webhook per batch; every lead in it is emitted above
  } else {
    // ---- web form ----
    const key = S(body.source_key || body.form_key || body.form || j.query && j.query.form);
    const ref = S(body.id || body.submission_id || body.entry_id);
    out.push({ json: {
      source: S(body.source) || 'web',
      source_key: key,
      page_id: '',
      leadgen_id: '',
      created_time: null,
      needsFetch: false,
      dedupe_key: ref ? 'web:' + key + ':' + ref : '',
      formData: body,
      sql: 'SELECT campaign_for($1) AS campaign, claim_once($2) AS fresh, $3::jsonb AS lead',
    } });
  }
}

// a blank dedupe key would collide across leads, so give those one of their own
return out.map((o) => {
  const d = o.json.dedupe_key || ('nokey:' + Date.now() + ':' + Math.random().toString(36).slice(2));
  return { json: { ...o.json, dedupe_key: d, params: [o.json.source_key, d, JSON.stringify(o.json)] } };
});

// ===== Normalize Lead =====
// Turns whatever arrived into one clean lead. The phone number is the important part:
// without a valid E.164 number there is nobody to message.
const loaded = $('Load Campaign').first().json;
const campaign = loaded.campaign || {};
const inbound = loaded.lead || {};
const fetched = $input.first().json || {};
const S = (v) => (v == null ? '' : String(v));
const flags = [];

// ---- phone -> E.164 ----
function toE164(raw, defaultCc) {
  let s = S(raw).trim();
  if (!s) return null;
  s = s.replace(/[^\d+]/g, '');
  if (s.slice(0, 2) === '00') s = '+' + s.slice(2);
  const cc = S(defaultCc).replace(/\D/g, '');
  if (s[0] === '+') {
    const d = s.slice(1);
    return /^[1-9]\d{7,14}$/.test(d) ? '+' + d : null;
  }
  let d = s.replace(/\D/g, '');
  if (!d) return null;
  if (d[0] === '0') {                                   // national format: 07700 900123
    if (!cc) return null;
    d = cc + d.replace(/^0+/, '');
  } else if (cc && d.slice(0, cc.length) === cc && d.length >= cc.length + 7) {
    // already carries the country code, just missing the +
  } else if (cc) {
    d = cc + d;
  }
  return /^[1-9]\d{7,14}$/.test(d) ? '+' + d : null;
}

// ---- pull the fields out of whichever source this came from ----
const raw = {};
let name = '', email = '', phone = '';

if (inbound.needsFetch) {                                // Meta returns field_data pairs
  for (const f of (fetched.field_data || [])) {
    const key = S(f.name).toLowerCase();
    const val = S((f.values || [])[0]).trim();
    if (!key) continue;
    raw[key] = val;
  }
  const first = raw.first_name || '';
  const last = raw.last_name || '';
  name = S(raw.full_name || (first + ' ' + last)).trim();
  email = S(raw.email || raw.email_address).trim().toLowerCase();
  phone = S(raw.phone_number || raw.phone || raw.mobile_number);
  raw.__meta = { leadgen_id: inbound.leadgen_id, ad_id: inbound.ad_id, form_id: inbound.source_key, page_id: inbound.page_id };
  if (!fetched.field_data) flags.push('META_LEAD_EMPTY');
} else {
  const f = inbound.formData || {};
  for (const k of Object.keys(f)) if (typeof f[k] !== 'object') raw[String(k).toLowerCase()] = S(f[k]);
  name = S(f.name || f.full_name || ((S(f.first_name) + ' ' + S(f.last_name)).trim()));
  email = S(f.email || f.email_address).trim().toLowerCase();
  phone = S(f.phone || f.phone_number || f.mobile || f.telephone);
}

const e164 = toE164(phone, campaign.default_country);
if (!e164) flags.push(phone ? 'PHONE_UNUSABLE' : 'PHONE_MISSING');
if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]{2,}$/.test(email)) { flags.push('EMAIL_INVALID'); email = ''; }

const clean = S(name).replace(/\s+/g, ' ').trim().slice(0, 80);
const parts = clean ? clean.split(' ') : [];

return [{
  json: {
    campaign,
    ok: !!e164,
    flags,
    lead: {
      phone: e164 || '',
      wa_id: e164 ? e164.slice(1) : '',
      name: clean,
      firstName: parts.length > 1 ? parts.slice(0, -1).join(' ') : (parts[0] || ''),
      lastName: parts.length > 1 ? parts[parts.length - 1] : '',
      email,
      source: inbound.source,
      source_ref: inbound.leadgen_id || inbound.dedupe_key,
      raw,
    },
    // the welcome template's variables, in the order the template declares them
    templateParams: [clean ? (parts[0] || clean) : 'there', S(campaign.name)],
    // A lead has not messaged us, so the first contact must be an approved template.
    // Their reply to it is what opens the 24-hour window for everything after.
    welcomePayload: e164 ? {
      messaging_product: 'whatsapp', recipient_type: 'individual', to: e164.slice(1), type: 'template',
      template: { name: S(campaign.welcome_template), language: { code: S(campaign.template_lang) || 'en' },
        components: [{ type: 'body', parameters: [
          { type: 'text', text: (clean ? (parts[0] || clean) : 'there').slice(0, 60) },
          { type: 'text', text: S(campaign.name).slice(0, 60) }] }] },
    } : null,
  },
}];
